// Renders the gallery from datesFolder/gallery.json (generated by scripts/build-gallery.mjs).
document.addEventListener("DOMContentLoaded", function () {
  const gallery = document.querySelector(".gallery");
  const jump = document.querySelector(".gallery-nav");

  const label = (date) => {
    const [y, m, d] = date.split("-").map(Number);
    return new Date(y, m - 1, d).toLocaleDateString("en-GB", { day: "numeric", month: "long", year: "numeric" });
  };

  // ---------- Lightbox ----------
  const lightbox = document.createElement("div");
  lightbox.className = "lightbox";
  lightbox.setAttribute("role", "dialog");
  lightbox.setAttribute("aria-modal", "true");
  lightbox.setAttribute("aria-label", "Photo viewer");
  lightbox.innerHTML =
    '<button class="close" aria-label="Close">&times;</button>' +
    '<button class="prev" aria-label="Previous photo">&#8249;</button>' +
    '<img alt="">' +
    '<button class="next" aria-label="Next photo">&#8250;</button>';
  document.body.appendChild(lightbox);
  const lightboxImg = lightbox.querySelector("img");

  let current = [];
  let index = 0;

  function show(i) {
    index = (i + current.length) % current.length;
    lightboxImg.src = current[index].full;
    lightboxImg.alt = current[index].alt;
  }
  function open(photos, i) {
    current = photos;
    show(i);
    lightbox.classList.add("open");
    lightbox.querySelector(".close").focus();
  }
  function close() { lightbox.classList.remove("open"); lightboxImg.removeAttribute("src"); }

  lightbox.addEventListener("click", (e) => {
    if (e.target.closest(".close") || e.target === lightbox) close();
    else if (e.target.closest(".prev")) show(index - 1);
    else if (e.target.closest(".next")) show(index + 1);
  });
  document.addEventListener("keydown", (e) => {
    if (!lightbox.classList.contains("open")) return;
    if (e.key === "Escape") close();
    if (e.key === "ArrowLeft") show(index - 1);
    if (e.key === "ArrowRight") show(index + 1);
  });

  // ---------- Render each day ----------
  fetch("datesFolder/gallery.json")
    .then((r) => r.json())
    .then(({ days }) => {
      if (!days.length) {
        gallery.innerHTML = '<p class="sub">No photos yet, check back soon.</p>';
        return;
      }
      days.forEach(({ date, photos }) => {
        const title = label(date);

        const link = document.createElement("a");
        link.href = "#d" + date;
        link.textContent = title;
        jump.appendChild(link);

        const group = document.createElement("section");
        group.className = "gallery-group";
        group.id = "d" + date;
        group.innerHTML = `<h2>${title}<small>${photos.length} photos</small></h2>`;

        const grid = document.createElement("div");
        grid.className = "photos";
        group.appendChild(grid);
        gallery.appendChild(group);

        const items = photos.map((p, n) => ({ ...p, alt: `#UmbracoTees day ${title}, photo ${n + 1}` }));
        items.forEach((item, n) => {
          const btn = document.createElement("button");
          btn.type = "button";
          btn.setAttribute("aria-label", `View photo ${n + 1} from ${title}`);
          const img = document.createElement("img");
          img.src = item.thumb;
          img.alt = item.alt;
          img.width = item.w;
          img.height = item.h;
          img.loading = "lazy";
          img.decoding = "async";
          btn.appendChild(img);
          btn.addEventListener("click", () => open(items, n));
          grid.appendChild(btn);
        });
      });
    })
    .catch((err) => {
      console.error("Error loading gallery:", err);
      gallery.innerHTML = '<p class="sub">Couldn’t load the gallery, try again soon.</p>';
    });
});
